CREATE TABLE `t_production_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `current_inventory` double DEFAULT NULL,
  `cycle_time` double DEFAULT NULL,
  `equipment` varchar(50) DEFAULT NULL,
  `finished_product_code` varchar(50) NOT NULL,
  `forecast` double DEFAULT NULL,
  `is_produce` varchar(2) DEFAULT NULL,
  `item_code` varchar(50) NOT NULL,
  `mold_cavity` int DEFAULT NULL,
  `operating_days` double DEFAULT NULL,
  `plan_qty` double DEFAULT NULL,
  `process` varchar(50) DEFAULT NULL,
  `safety_days` double DEFAULT NULL,
  `scrap_rate` double DEFAULT NULL,
  `staff_count` double DEFAULT NULL,
  `takt_time` double DEFAULT NULL,
  `version` varchar(50) DEFAULT NULL,
  `year_month` int NOT NULL,
  `manufacturing_department` varchar(50) DEFAULT NULL,
  `manufacturing_unit` varchar(50) DEFAULT NULL,
  `calculated_at` datetime DEFAULT NULL COMMENT '计算时间',
  `raw_plan_qty` double DEFAULT NULL,
  `part_attribute` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=572740 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
